"use client";

import { useRouter } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { listRuns, listSpecs } from "@/lib/api";
import { useWorkspace } from "@/lib/workspace";
import { Badge, Button, Card } from "@/components/ui/primitives";
import type { SpecRow } from "@/lib/types";

function Runs({ spec }: { spec: SpecRow }) {
  const { tenantId } = useWorkspace();
  const q = useQuery({ queryKey: ["runs", spec.id, tenantId], queryFn: () => listRuns(spec.id, tenantId) });
  if (q.isLoading) return <p className="p-4 text-xs text-muted">Loading runs</p>;
  if (q.isError) return <p className="p-4 text-xs text-bad">{String(q.error)}</p>;
  if (!q.data?.length) return <p className="p-4 text-xs text-muted">No generation runs for this spec yet.</p>;
  return (
    <ul className="divide-y divide-line">
      {q.data.map((r) => (
        <li key={r.id} className="space-y-1 px-4 py-3 text-xs">
          <div className="flex items-center gap-2">
            <Badge tone={r.status.startsWith("generated") ? "good" : r.status === "error" ? "bad" : "warn"}>{r.status.replaceAll("_", " ")}</Badge>
            <span className="text-muted">{r.createdAt ? new Date(r.createdAt).toLocaleString() : ""}</span>
          </div>
          {r.error && <p className="text-bad">{r.error}</p>}
          {r.cql && <pre className="max-h-40 overflow-auto rounded-lg bg-surface2 p-2 font-mono text-[11px]">{r.cql}</pre>}
        </li>
      ))}
    </ul>
  );
}

export default function Library() {
  const { tenantId, loadSpec } = useWorkspace();
  const router = useRouter();
  const [open, setOpen] = useState<string | null>(null);
  const q = useQuery({ queryKey: ["specs", tenantId], queryFn: () => listSpecs(tenantId) });

  return (
    <div className="mx-auto max-w-4xl space-y-5">
      <div>
        <h1 className="text-xl font-semibold tracking-tight">Spec library</h1>
        <p className="mt-1 text-sm text-muted">Every spec submitted under tenant <span className="font-mono">{tenantId}</span>, with its generation runs.</p>
      </div>
      {q.isError && <p className="rounded-lg bg-badsoft p-3 text-sm text-bad">{String(q.error)}</p>}
      {q.data?.length === 0 && <Card><p className="p-8 text-center text-sm text-muted">Nothing here yet. Run a spec in the workspace and it will appear.</p></Card>}
      <div className="space-y-3">
        {(q.data ?? []).map((s) => (
          <Card key={s.id}>
            <div className="flex items-start gap-3 p-4">
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2"><span className="font-mono text-sm font-semibold">{s.reportId}</span><span className="text-xs text-muted">{s.createdAt ? new Date(s.createdAt).toLocaleDateString() : ""}</span></div>
                <p className="mt-1 line-clamp-2 text-sm text-muted">{s.description}</p>
              </div>
              <Button variant="ghost" onClick={() => setOpen(open === s.id ? null : s.id)} aria-expanded={open === s.id}>Runs</Button>
              <Button
                onClick={() => {
                  loadSpec({ reportId: s.reportId, description: s.description, columnHeading: s.columnHeading, logic: s.logic, reportScenarios: s.reportScenarios, sorting: s.sorting });
                  router.push("/");
                }}
              >
                Open
              </Button>
            </div>
            {open === s.id && <div className="border-t border-line"><Runs spec={s} /></div>}
          </Card>
        ))}
      </div>
    </div>
  );
}
